#include <vector>
#include <type_traits>

int main() {
    std::vector<int> v = {1, 2, 3};

    // Vector iterators are Random Access
    auto it = v.begin();
    it += 2; // O(1) operation guaranteed

    // Checking if the iterator is a raw pointer (Implementation Dependent!)
    if (std::is_pointer<decltype(v.begin())>::value) {
        // This branch is only taken if implemented as raw pointer (e.g., GCC/Clang release builds)
        // relying on this is non-portable.
    }

    // Safe way to get contiguous pointer (C++11 onward):
    int* raw_ptr = v.data(); 
    // Use standard iterator operations, not raw pointer assumptions.
}
